export const getArticleBySlug = (slug: string): ArticleData | undefined => {
  return ARTICLES_DATA.find(a => a.slug === slug);
};

export const getArticleById = (id: string): ArticleData | undefined => {
  return ARTICLES_DATA.find(a => a.id === id);
};
